input.value:
timeseries {
  successful = max(custom.exchange.submission.successful_submissions_per_sec),
  tempFailures = max(custom.exchange.submission.temporary_submission_failures_per_sec),
  failed = max(custom.exchange.submission.failed_submissions_per_sec),
  pending = max(custom.exchange.submission.messages_queued_for_submission)
}, by: {exchange.server}, from: now() - 1h, interval: 1m

timeseries {
  running = min(custom.exchange.service.running, scalar: true),
  present = max(custom.exchange.service.present, scalar: true)
}, by: {exchange.server, service, label}, from: now() - 15m
| filter present == 1 and running == 0
| sort server asc, service asc
